def parse_parameters(param_str: str) -> dict[str, str]:
    """Parse protoc plugin parameters in key=value format."""
    if not param_str:
        return {}

    params: dict[str, str] = {}
    for pair in param_str.split(","):
        key, _, value = pair.partition("=")
        params[key] = value
    return params


def collect_type_owners(
    package_name: str,
    proto_file: str,
    message,
    parents: tuple[str, ...],
    owners: dict[str, tuple[str, str, tuple[str, ...]]],
) -> None:
    """Collect fully-qualified message owners, including nested messages."""
    path = (*parents, message.name)
    full_name = ".".join((*([package_name] if package_name else []), *path))
    owners[full_name] = (package_name, proto_file, path)
    for nested in message.nested_type:
        collect_type_owners(package_name, proto_file, nested, path, owners)


def normalize_proto_path(value: str) -> str:
    """Normalize a descriptor path for stable cross-language metadata."""
    normalized = value.replace("\\", "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    return normalized if normalized.endswith(".proto") else f"{normalized}.proto"


def to_snake_case(name: str) -> str:
    """Convert CamelCase names to snake_case."""
    import re

    normalized = name.replace(".", "_").replace("-", "_")
    s1 = re.sub("(.)([A-Z][a-z]+)", r"\1_\2", normalized)
    return re.sub("([a-z0-9])([A-Z])", r"\1_\2", s1).lower()


